const items = $input.all();

const inventory = [
  { type: "apartment", min: 150000, max: 300000 },
  { type: "house", min: 250000, max: 500000 },
  { type: "luxury", min: 500000, max: 1000000 }
];

const getField = (obj, ...names) => {
  for (const name of names) {
    const key = Object.keys(obj).find(
      k => k.toLowerCase().trim() === name.toLowerCase()
    );

    if (key !== undefined && obj[key] !== null &&
        String(obj[key]).trim() !== "") {
      return obj[key];
    }
  }
  return "";
};

const getBudget = value => {
  if (typeof value === "number") return value;

  const cleaned = String(value ?? "")
    .replace(/[$,\s]/g, "");

  if (!cleaned || !/^\d+(\.\d+)?$/.test(cleaned)) {
    return null;
  }

  return Number(cleaned);
};

const leads = items
  .map((item, index) => ({
    originalIndex: index,
    data: item.json
  }))
  .filter(({ data }) =>
    String(getField(data, "Status")).trim().toLowerCase() === "new"
  )
  .map(({ data, originalIndex }) => {
    const name = getField(data, "Name");
    const email = getField(data, "Email");
    const phone = getField(data, "Phone");
    const budgetRaw = getField(data, "Budget");
    const sourceRaw = getField(data, "Source");
    const inquiry = getField(data, "Inquiry");

    const budget = getBudget(budgetRaw);
    const source = String(sourceRaw).trim().toLowerCase();

    let priority = "Low";
    let reason = "";
    let budgetMatches = false;

    const missing = [];

    if (!name) missing.push("Name");
    if (!email) missing.push("Email");
    if (!phone) missing.push("Phone");
    if (!budgetRaw || budget === null) missing.push("valid Budget");
    if (!sourceRaw) missing.push("Source");
    if (!inquiry) missing.push("Inquiry");

    const text = String(inquiry).toLowerCase();

    let propertyType = null;

    if (/\bluxury\b/.test(text)) {
      propertyType = "luxury";
    } else if (/\b(apartment|apartments|condo|condos|flat|flats)\b/.test(text)) {
      propertyType = "apartment";
    } else if (/\b(house|houses|home|homes)\b/.test(text)) {
      propertyType = "house";
    }

    if (missing.length > 0) {
      reason = `Incomplete information: missing ${missing.join(", ")}.`;
    } else {
      const suitableInventory = propertyType
        ? inventory.filter(p => p.type === propertyType)
        : inventory;

      budgetMatches = suitableInventory.some(
        p => budget >= p.min && budget <= p.max
      );

      if (!budgetMatches) {
        reason = propertyType
          ? `Budget does not match the available ${propertyType} inventory range.`
          : "Budget does not match any defined inventory range.";
      } else if (
        source === "referral" ||
        source === "hot listing"
      ) {
        priority = "High";
        reason = `Budget matches available inventory and lead came through ${source}.`;
      } else if (
        source === "cold lead" ||
        source === "advertisement"
      ) {
        priority = "Medium";
        reason = `Budget matches available inventory, but the source is ${source}.`;
      } else {
        reason = `Source "${sourceRaw}" does not meet the defined High or Medium Priority rules.`;
      }
    }

    let followUp = "";

    if (priority === "High") {
      const interest = inquiry
        ? `your interest in ${String(inquiry).trim().replace(/[.!?]+$/, "")}`
        : "your property inquiry";

      followUp =
        `Hi ${name}, thank you for ${interest}. Your budget appears to match our available inventory.\n` +
        "Would you be available for a quick call to discuss suitable properties?";
    }

    return {
      originalIndex,
      name,
      email,
      phone,
      budget: budgetRaw,
      source: sourceRaw,
      inquiry,
      status: "New",
      priority,
      reason,
      followUp
    };
  });

const priorityRank = {
  High: 1,
  Medium: 2,
  Low: 3
};

leads.sort((a, b) =>
  priorityRank[a.priority] - priorityRank[b.priority] ||
  a.originalIndex - b.originalIndex
);

const high = leads.filter(l => l.priority === "High");
const medium = leads.filter(l => l.priority === "Medium");
const low = leads.filter(l => l.priority === "Low");

return [
  {
    json: {
      title: "Lead Triage Results",
      new_leads_processed: leads.length,
      high_priority_count: high.length,
      medium_priority_count: medium.length,
      low_priority_count: low.length,
      leads: leads.map(({ originalIndex, ...lead }) => lead),
      high_priority_follow_ups: high.map(l => ({
        name: l.name,
        phone: l.phone,
        message: l.followUp
      })),
      data_quality_issues: low
        .filter(l => l.reason.startsWith("Incomplete information"))
        .map(l => ({
          name: l.name || "Unknown",
          reason: l.reason
        })),
      connector_issues: [],
      message: leads.length === 0
        ? "No new leads were found in the input data."
        : "Lead triage completed."
    }
  }
];

const data = $input.first().json;

const leads = Array.isArray(data.leads)
  ? data.leads
  : [];

const highLeads = leads.filter(lead =>
  String(lead.priority ?? "").trim().toLowerCase() === "high"
);

const high_priority_follow_ups = highLeads.map(lead => {
  const name = String(lead.name ?? "Customer").trim();

  const inquiry = String(lead.inquiry ?? "").trim();

  let message = String(
    lead.followUpMessage ?? lead.followUp ?? ""
  ).trim();

  if (!message) {
    message =
      `Hi ${name}, thank you for your inquiry` +
      (inquiry ? ` about ${inquiry}` : " about our properties") +
      ". Your budget appears to match our available inventory.\n\n" +
      "Would you be available for a quick call to discuss suitable properties?";
  }

  return {
    name: name,
    email: String(lead.email ?? "").trim(),
    phone: String(lead.phone ?? "").trim(),
    budget: lead.budgetLabel ?? lead.budget ?? "",
    inquiry: inquiry,
    priority: "High",
    message: message
  };
}).filter(customer =>
  customer.email !== "" &&
  customer.message !== ""
);

return high_priority_follow_ups.map(customer => ({
  json: customer
}));
